package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Entry is a single line in the ledger.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// Column widths for the ledger table.
const (
	dateWidth        = 10
	descriptionWidth = 25
	changeWidth      = 13
)

var (
	errInvalidCurrency = errors.New("invalid currency")
	errInvalidLocale   = errors.New("invalid locale")
	errInvalidDate     = errors.New("invalid date")
)

// FormatLedger renders entries as a formatted ledger table for the given
// currency ("USD" or "EUR") and locale ("en-US" or "nl-NL").
//
// Refactoring log (per the exercise instructions):
//
//  1. Validate the currency and locale once, up front, instead of the
//     recursive call used to validate an empty ledger and the repeated
//     per-row checks scattered through the goroutines.
//  2. Replace the hand-rolled bubble sort (with its boolean-to-sign lookup
//     maps) with sort.Slice, comparing date, then description, then change.
//  3. Replace the goroutine/channel fan-out with a plain sequential loop;
//     the work is trivial and the concurrency only added complexity.
//  4. Extract date parsing/formatting into formatDate, which returns a
//     proper error for malformed dates.
//  5. Extract description truncation into truncate.
//  6. Extract amount formatting into formatAmount, with the locale-specific
//     rules (thousands separator, decimal separator, negative marker) in one
//     place.
//  7. Build rows with fmt.Sprintf padding instead of hand-rolled
//     strings.Repeat arithmetic.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	if currency != "USD" && currency != "EUR" {
		return "", errInvalidCurrency
	}
	if locale != "en-US" && locale != "nl-NL" {
		return "", errInvalidLocale
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(header(locale))
	for _, e := range sorted {
		row, err := formatRow(currency, locale, e)
		if err != nil {
			return "", err
		}
		b.WriteString(row)
	}
	return b.String(), nil
}

func header(locale string) string {
	date, description, change := "Date", "Description", "Change"
	if locale == "nl-NL" {
		date, description, change = "Datum", "Omschrijving", "Verandering"
	}
	return fmt.Sprintf("%-*s | %-*s | %s\n", dateWidth, date, descriptionWidth, description, change)
}

func formatRow(currency, locale string, e Entry) (string, error) {
	date, err := formatDate(locale, e.Date)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("%-*s | %-*s | %*s\n",
		dateWidth, date,
		descriptionWidth, truncate(e.Description),
		changeWidth, formatAmount(currency, locale, e.Change)), nil
}

// formatDate converts "Y-m-d" to the locale's display format and rejects
// anything that is not exactly 10 characters with '-' separators.
func formatDate(locale, date string) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", errInvalidDate
	}
	if locale == "nl-NL" {
		return date[8:10] + "-" + date[5:7] + "-" + date[0:4], nil
	}
	return date[5:7] + "/" + date[8:10] + "/" + date[0:4], nil
}

// truncate shortens descriptions longer than the column width, marking the
// cut with an ellipsis.
func truncate(s string) string {
	if len(s) > descriptionWidth {
		return s[:descriptionWidth-3] + "..."
	}
	return s
}

// formatAmount renders cents in the locale's convention:
//
//	en-US: $1,234.56, negatives as ($1,234.56)
//	nl-NL: $ 1.234,56, negatives marked with a trailing '-'
func formatAmount(currency, locale string, cents int) string {
	negative := cents < 0
	if negative {
		cents = -cents
	}
	sign := currencySymbol(currency)
	dollars := thousandsSep(locale, cents/100)
	frac := fmt.Sprintf("%02d", cents%100)
	if locale == "nl-NL" {
		suffix := " "
		if negative {
			suffix = "-"
		}
		return sign + " " + dollars + "," + frac + suffix
	}
	if negative {
		return "(" + sign + dollars + "." + frac + ")"
	}
	return sign + dollars + "." + frac + " "
}

func currencySymbol(currency string) string {
	if currency == "EUR" {
		return "€"
	}
	return "$"
}

// thousandsSep groups the integer part of an amount in threes using the
// locale's thousands separator (',' in en-US, '.' in nl-NL).
func thousandsSep(locale string, n int) string {
	sep := ","
	if locale == "nl-NL" {
		sep = "."
	}
	s := strconv.Itoa(n)
	if len(s) <= 3 {
		return s
	}
	var b strings.Builder
	for i, r := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteString(sep)
		}
		b.WriteRune(r)
	}
	return b.String()
}

